  'hcp/psp': {
    section: 'Healthcare',
    title: 'RWE data analysis and processing systems',
    h1Line1: 'RWE data analysis',
    h1Accent: 'and processing systems',
    lede: 'Platforms for collecting and analyzing real-world clinical data for healthcare, drug manufacturers, and medical device makers: cohort analytics, AI-powered data processing, therapy effectiveness evidence, and outcomes-based contract models.',
    tags: ['RWE', 'RealWorldEvidence', 'ClinicalData', 'HealthcareAnalytics', 'PharmaStrategy'],
    artSlides: [
      { src: 'assets/uploads/hcp-rwe-detail-slide-1.png?v=20260527', label: 'Real-world evidence', alt: 'RWE data analysis systems: dashboards, cloud storage, and clinical data analytics' },
    ],
    aboutTitle: 'Real-world clinical data as a strategic asset',
    about: [
      'Real-World Evidence (RWE) is clinical data on use, safety, and effectiveness collected outside controlled trials—from EHRs, registries, pharmacy data, mobile apps, and patient surveys. Regulators increasingly accept RWE as evidence for expanding the range of indications, faster registration, and pricing—turning real-world data systems from a trial add-on into strategic commercial infrastructure.',
    ],
    featuresTitle: 'Pick a direction',
    features: [
      { t: 'Cohort platform / De-identified analytics / Subscription model', d: 'Aggregated, de-identified cohort data is offered to pharmaceutical companies as platform access—not raw datasets—a distinction critical under personal data protection law. Manufacturers receive quarterly analytics reports: clinical trends during therapy, dose-adjustment frequency, real-world adverse-event profiles—without transferring personal patient information.' },
      { t: 'Sponsored observational study / Cohort sponsorship / RWE as a service', d: 'The platform acts as a digital CRO: the company funds a specific observational study on a live app cohort—not a database—generating PASS/NIS-grade evidence faster and cheaper than traditional sites.' },
      { t: 'Outcomes-based contract / Value-Based Contracting / Outcomes-Based Agreement', d: 'Payers bundle the digital service against KPIs—fewer hospitalizations, better adherence, fewer repeat visits. Full payment if KPIs are met, adjusted if not. The most scalable RWE monetization model; since 2022, 58%+ of mature-market payers had at least one such contract.' },
      { t: 'Back-end AI analytics / NLP and ML / Automated data cleaning', d: 'Back-end AI standardizes streams to SDTM/OMOP, finds gaps and anomalies, builds comparative cohorts, and drafts regulatory narratives—cutting time from data capture to insight from months to weeks.' },
    ],
    stepsTitle: 'When an RWE platform is truly needed',
    steps: [
      { n: '01', t: 'Label expansion and regulatory dossier support', d: 'Regulators accept RWE as supporting evidence for label expansion—especially in oncology, in rare diseases, and in pediatrics, where RCTs are hard or impractical. An accumulated real-world cohort becomes ready evidence for submission.' },
      { n: '02', t: 'Payer negotiations and product pricing', d: 'At launch or reimbursement defense, own RWE on real effectiveness in defined cohorts is hard to refute. Manufacturers with RWE infrastructure secure better formulary terms.' },
      { n: '03', t: 'Post-marketing surveillance and PASS obligations', d: 'Approval often requires PASS studies. A digital RWE platform fulfills obligations on larger cohorts, with high data quality and shorter timelines than traditional approaches.' },
      { n: '04', t: 'Outcomes-based contracts with payers', d: 'In outcomes-based contracting, real clinical outcomes are the settlement asset. Whoever delivers verifiable RWE on agreed KPIs (hospitalizations, adherence, disease control) on time gains financial reward and long-term negotiating edge.' },
    ],
    stepsRegulatory: {
      title: 'Regulatory framework and key principles for working with RWD',
      intro: 'Building real-world clinical data systems requires mandatory conditions that define not only legal compliance but value for regulators and payers:',
      items: [
        { t: 'De-identification and access boundaries', d: 'Manufacturers access an analytics environment with aggregated results—not personal patient data—reducing personal data protection law risk and supporting a legally sound commercial model.' },
        { t: 'Data standardization for regulatory formats', d: 'Data for regulatory submissions must meet structuring standards (SDTM, OMOP CDM) and source-quality requirements—built into platform architecture from day one, not retrofitted before filing.' },
        { t: 'Informed consent and transparency', d: 'Every cohort participant—patient or HCP—completes informed consent describing purposes and limits of use, including commercial. eCONSENT screens are embedded in the app or platform UI.' },
        { t: 'Human-in-the-loop for AI outputs', d: 'AI speeds and automates information processing, but regulatorily meaningful conclusions and reports are verified by qualified experts—a standard on leading RWE platforms combining automation speed with expert validation.' },
      ],
    },
    deliverablesTitle: 'Problems it solves',
    deliverables: [
      { t: 'Gap between trial data and real-world practice', d: 'RCT results often differ from daily practice. An RWE platform closes the gap with real-world effectiveness evidence—for regulators, payers, and the medical community.' },
      { t: 'High cost and duration of traditional clinical trials', d: 'Classic trials take years and major investment. Using accumulated RWD cohorts can cut sample size 30–50% and speed evidence for label expansion and pricing.' },
      { t: 'No evidence base for payer negotiations', d: 'Insurers and reimbursement systems increasingly want real-world—not only clinical—proof. A built RWE infrastructure brings concrete data to formulary negotiations.' },
      { t: 'Regulatory complexity for real-world data', d: 'Medical data needs de-identification, privacy protection, and regulatory formats. Architecture that grants access to analytics—not raw data—reduces legal risk and enables lawful monetization.' },
      { t: 'Unstructured accumulated clinical data', d: 'Notes, reports, labs, and surveys sit in fragmented formats. NLP and AI back-end extract structured data and make it analysis-ready.' },
      { t: 'Delayed post-marketing safety signals', d: 'Traditional pharmacovigilance relies on incomplete voluntary reporting. Continuous cohort monitoring surfaces adverse-event signals in real time—well before classic PV systems.' },
    ],
  },

