  'content/gamification': {
    section: 'Design',
    title: 'Games, quizzes, and clinical detective stories for HCP',
    h1Line1: 'Games, quizzes, and',
    h1Accent: 'clinical detective stories',
    h1Accent2: 'for HCP',
    lede: 'Clinical detective stories, quizzes, and case games for physicians and pharmacists—pharma gamification that educates, engages, and builds brand loyalty.',
    tags: ['MedicalGamification', 'SeriousGames', 'HCPengagement', 'ClinicalQuiz', 'PharmaEducation'],
    artSlides: [
      { src: 'assets/uploads/content-gamification-detail.png?v=20260528', label: 'Gamification for HCP', alt: 'HCP games and quizzes: clinical detective illustration' },
    ],
    aboutTitle: 'Games in medicine for serious learning',
    about: [
      'Gamification in medical education and pharma marketing is not entertainment for its own sake—it is evidence-based engagement, knowledge retention, and clinical reasoning for physicians and pharmacists. Game formats can reach 95–97% program completion versus traditional modules and sustain professional interest beyond work hours. For brands, it is a unique way to embed key messages emotionally in the clinical experience.',
    ],
    featuresTitle: 'Pick a game format',
    features: [
      { t: 'Clinical detective / Diagnostic case / Branching narrative', d: 'The most immersive format: from first visit through history, labs, and imaging to diagnosis and treatment—each choice shapes the case like real clinical thinking, with depth slides cannot match. Serial cases and a virtual patient “journey” build long-term platform loyalty.' },
      { t: 'Quiz / Knowledge contest / Leaderboards and rankings', d: 'Quizzes on disease, diagnosis, and therapy activate congress, webinar, and messenger audiences instantly—healthy competition, instant feedback, scalable from a one-minute hall quiz to a multi-stage challenge with points.' },
      { t: 'Patient portrait / Comorbid case / Decision-making', d: 'Focused on a patient archetype: analyze history, complaints, and workup to build a management plan with comorbidity and goals—ideal for native, non-promotional demonstration of the brand’s clinical edge as HCPs discover the message through the case.' },
      { t: 'AI-adaptive game / Personalized learning path / VR/AR simulator', d: 'AI adjusts difficulty and topics to specialty and level; VR/AR enables virtual exams, 3D pathology, and safe procedural practice without patient risk.' },
    ],
    stepsTitle: 'Gamification—when it truly matters',
    steps: [
      { n: '01', t: 'Brand promotion in a native clinical context', d: 'When direct promo hits skepticism or regulatory limits, a clinical case with a native treatment algorithm lets physicians reach product advantages themselves—without ad pressure. That builds conviction, not just awareness.' },
      { n: '02', t: 'HCP training on a new product or indication', d: 'At launch or label expansion, game scenarios speed deep mastery of clinical profile—indications, positioning, objection handling practiced in safe simulation, not only declared in the label.' },
      { n: '03', t: 'HCP loyalty and brand ambassadors', d: 'Regular quality interaction with a brand education platform builds knowledge and positive association—loyalty and future KOLs without aggressive promotion.' },
      { n: '04', t: 'Audience engagement at congresses, webinars, and meetings', d: 'Live quizzes, team detectives, and knowledge contests turn passive listeners into active participants—better recall, event engagement, and NPS for the organizing brand.' },
    ],
    deliverablesTitle: 'Games help you win—problems you can play through',
    deliverables: [
      { t: 'Low engagement with traditional education formats', d: 'Linear lectures and PDFs lose the busy physician’s attention. Game formats activate cognitive and emotional engagement—problem-solving mode learns deeper and retains longer than passive viewing.' },
      { t: 'Weak knowledge retention after one-off events', d: 'Lecture content fades in days without repetition. Staged play, instant feedback, and revisiting hard questions implement spaced repetition for long-term retention.' },
      { t: 'Hard to deliver brand messages in non-promotional context', d: 'HCPs filter overt promotion. Clinical detectives and case games embed the message in narrative—specialists discover therapeutic advantages through the decision.' },
      { t: 'Insufficient motivation for continuous learning', d: 'Points, rankings, badges, certificates, and unlock levels build external and internal motivation for regular, not one-off, engagement with the education platform. Evidence shows gamified programs form durable learning habits.' },
      { t: 'Hard to assess real HCP competence', d: 'Classic tests show “right answer” recall, not clinical application. Branching cases and simulations assess thinking in action—for the physician and the program owner.' },
      { t: 'Hard to hold audience at multi-day congresses and webinars', d: 'Passive listening tires delegates. Between-session quizzes, live contests, booth activity rankings, and team games restore attention and positive brand association.' },
    ],
  },

